-- Activate the remaining canonical PDK identities (2007..2028).
--
-- V20261002_01 created the canonical game rows but intentionally left these
-- 22 identities on legacy-equivalent-1.  This forward migration publishes a
-- new immutable release/index generation under <gameCode>-v1.0.0, then moves
-- the active pointers.  Historical releases and rows are retained for replay
-- and room recovery; only their operational status is retired.
--
-- The rule fields below are generated from the already-registered authoritative
-- workbooks.  They are embedded in this migration so applying it never reads
-- a mutable workspace file or a production service.

SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
START TRANSACTION;

CREATE TEMPORARY TABLE remaining_canonical_pdk (
  game_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  game_code VARCHAR(64) NOT NULL UNIQUE,
  old_code VARCHAR(32) NOT NULL UNIQUE,
  old_version VARCHAR(64) NOT NULL,
  play_version VARCHAR(64) NOT NULL UNIQUE,
  region_code VARCHAR(32) NOT NULL,
  source_hash CHAR(64) NOT NULL,
  rule_fields JSON NOT NULL
);

