"order":20,"disabled":false},{"value":10,"label":"10分钟","order":30,"disabled":false},{"value":12,"label":"12分钟","order":40,"disabled":false},{"value":15,"label":"15分钟","order":50,"disabled":false},{"value":20,"label":"20分钟","order":60,"disabled":false}]},{"key":"dissolveTimeoutSeconds","label":"解散时间","control":"radio","order":170,"visible":true,"disabled":false,"required":true,"defaultCandidateIndexes":[1],"defaultValue":30,"options":[{"value":30,"label":"30秒解散","order":10,"disabled":false},{"value":60,"label":"1分解散","order":20,"disabled":false},{"value":180,"label":"3分解散","order":30,"disabled":false},{"value":300,"label":"5分解散","order":40,"disabled":false},{"value":-1,"label":"不可解散","order":50,"disabled":false}]},{"key":"roomRestriction","label":"其他","control":"checkbox","order":180,"visible":true,"disabled":false,"required":false,"defaultCandidateIndexes":[1],"defaultValue":["same_ip_blocked"],"options":[{"value":"same_ip_blocked","label":"同IP不可进","order":10,"disabled":false},{"value":"within_100m_blocked","label":"100米内不可进","order":20,"disabled":false},{"value":"items_forbidden","label":"禁止使用道具","order":30,"disabled":false},{"value":"within_200m_blocked","label":"200米内不可进","order":40,"disabled":false},{"value":"kick_unready_30s","label":"30秒未准备自动踢出房间","order":50,"disabled":false},{"value":"voice_forbidden","label":"禁止语音","order":60,"disabled":false},{"value":"chat_forbidden","label":"禁止文字","order":70,"disabled":false}]}]' AS JSON) WHERE game_id=2027;
UPDATE remaining_canonical_pdk SET rule_fields=CAST('[{"key":"roundCount","label":"局数","control":"radio","order":80,"visible":true,"disabled":false,"required":true,"defaultCandidateIndexes":[1],"defaultValue":8,"options":[{"value":8,"label":"8局","order":10,"disabled":false},{"value":16,"label":"16局","order":20,"disabled":false},{"value":24,"label":"24局","order":30,"disabled":false}]},{"key":"playerCount","label":"人数","control":"radio","order":90,"visible":true,"disabled":false,"required":true,"defaultCandidateIndexes":[1],"defaultValue":2,"options":[{"value":2,"label":"2人","order":10,"disabled":false},{"value":3,"label":"3人","order":20,"disabled":false}]},{"key":"paymentMode","label":"支付方式","control":"radio","order":100,"visible":true,"disabled":false,"required":true,"defaultCandidateIndexes":[1],"defaultValue":"owner_pays","options":[{"value":"owner_pays","label":"房主付","order":10,"disabled":false},{"value":"split_pays","label":"平分付","order":20,"disabled":false},{"value":"winner_pays","label":"胜家付","order":30,"disabled":false}]},{"key":"dealCardCount","label":"发牌张数","control":"radio","order":110,"visible":true,"disabled":false,"required":true,"defaultCandidateIndexes":[1],"defaultValue":15,"options":[{"value":15,"label":"15张","order":10,"disabled":false},{"value":16,"label":"16张","order":20,"disabled":false}]},{"key":"baseScore","label":"底分","control":"radio","order":120,"visible":true,"disabled":false,"required":true,"defaultCandidateIndexes":[1],"defaultValue":1,"options":[{"value":1,"label":"1分","order":10,"disabled":false},{"value":2,"label":"2分","order":20,"disabled":false},{"value":5,"label":"5分","order":30,"disabled":false},{"value":10,"label":"10分","order":40,"disabled":false}]},{"key":"playRule","label":"玩法与设置","control":"checkbox","order":130,"visible":true,"disabled":false,"required":false,"defaultCandidateIndexes":[1],"defaultValue":["must_beat"],"options":[{"value":"must_beat","label":"必须管","order":10,"disabled":false},{"value":"winner_first","label":"胜家先出","order":20,"disabled":false},{"value":"must_beat_on_run","label":"逢跑必压","order":30,"disabled":false},{"value":"auto_pass","label":"自动过牌","order":40,"disabled":false},{"value":"show_hand","label":"显示手牌","order":50,"disabled":false},{"value":"last_card_scoring","label":"尾张算分","order":60,"disabled":false},{"value":"four_with_three","label":"四带三","order":70,"disabled":false}]},{"key":"bombScore","label":"炸弹记分","control":"radio","order":140,"visible":true,"disabled":false,"required":true,"defaultCandidateIndexes":[1],"defaultValue":0,"options":[{"value":0,"label":"炸弹不算分","order":10,"disabled":false},{"value":5,"label":"炸弹加5分","order":20,"disabled":false},{"value":10,"label":"炸弹加10分","order":30,"disabled":false}]},{"key":"roomSettings","label":"房间设置","control":"checkbox","order":150,"visible":true,"disabled":false,"required":false,"defaultCandidateIndexes":[1],"defaultValue":["switch_player_count"],"options":[{"value":"switch_player_count","label":"房间内切换人数","order":10,"disabled":false}]},{"key":"operationTimeoutSeconds","label":"操作时间","control":"radio","order":160,"visible":true,"disabled":false,"required":true,"defaultCandidateIndexes":[1],"defaultValue":-1,"options":[{"value":-1,"label":"不限制","order":10,"disabled":false},{"value":180,"label":"3分出牌","order":20,"disabled":false},{"value":300,"label":"5分出牌","order":30,"disabled":false},{"value":60,"label":"1分出牌","order":40,"disabled":false},{"value":30,"label":"30秒出牌","order":50,"disabled":false}]},{"key":"dissolveTimeoutSeconds","label":"解散时间","control":"radio","order":170,"visible":true,"disabled":false,"required":true,"defaultCandidateIndexes":[1],"defaultValue":30,"options":[{"value":30,"label":"30秒解散","order":10,"disabled":false},{"value":60,"label":"1分解散","order":20,"disabled":false},{"value":180,"label":"3分解散","order":30,"disabled":false},{"value":300,"label":"5分解散","order":40,"disabled":false},{"value":-1,"label":"不可解散","order":50,"disabled":false}]},{"key":"roomRestriction","label":"其他","control":"checkbox","order":180,"visible":true,"disabled":false,"required":false,"defaultCandidateIndexes":[1],"defaultValue":["same_ip_blocked"],"options":[{"value":"same_ip_blocked","label":"同IP不可进","order":10,"disabled":false},{"value":"same_location_blocked","label":"同位置不可进","order":20,"disabled":false},{"value":"items_forbidden","label":"禁止使用道具","order":30,"disabled":false}]}]' AS JSON) WHERE game_id=2028;
-- v1.20 publication operations follow the seeded identity mapping.
-- The publisher adds payerMode as the server-owned billing field.  It must be
-- part of the validator but is deliberately not exposed as a workbook UI
-- field.  Existing room-rule field values remain the source of truth.
CREATE TEMPORARY TABLE remaining_canonical_pdk_validator AS
SELECT game_id,
       JSON_ARRAY_APPEND(rule_fields,'$',JSON_OBJECT(
         'key','payerMode','label','支付方式','order',10000,'control','radio',
         'visible',false,'disabled',false,'required',true,
         'defaultValue','OWNER','options',JSON_ARRAY(JSON_OBJECT(
           'value','OWNER','label','房主支付','order',10,'disabled',false)))) fields
FROM remaining_canonical_pdk;

-- The canonical play-version row already exists for every target because
-- V20261002_01 created the game identities.  Copy its schema/compatibility
-- contract while changing only the play-version identity and content hash.
INSERT INTO aoo_play_version
  (game_id,play_version,default_region_code,rule_schema_version,ui_schema_version,
   component_schema_version,content_hash,status,compatibility_floor,activated_at,created_by)
SELECT m.game_id,m.play_version,p.default_region_code,p.rule_schema_version,p.ui_schema_version,
       p.component_schema_version,
       SHA2(CONCAT('canonical-pdk|',m.game_code,'|',m.play_version,'|',m.source_hash),256),
       'ACTIVE',p.compatibility_floor,CURRENT_TIMESTAMP(3),p.created_by
FROM remaining_canonical_pdk m
JOIN aoo_play_version p ON p.game_id=m.game_id AND p.play_version=m.old_version
WHERE p.status IN ('ACTIVE','VALIDATED')
ON DUPLICATE KEY UPDATE
  default_region_code=VALUES(default_region_code),rule_schema_version=VALUES(rule_schema_version),
  ui_schema_version=VALUES(ui_schema_version),component_schema_version=VALUES(component_schema_version),
  content_hash=VALUES(content_hash),status='ACTIVE',compatibility_floor=VALUES(compatibility_floor),
  activated_at=COALESCE(aoo_play_version.activated_at,VALUES(activated_at)),retired_at=NULL;

-- Publish a distinct route row; the old route remains historical until the
-- final retirement statements below.
INSERT INTO aoo_game_service_route
  (route_id,game_id,play_version,endpoint,priority,status)
SELECT m.game_id*1000000+2026100603,m.game_id,m.play_version,r.endpoint,r.priority,'ACTIVE'
FROM remaining_canonical_pdk m
JOIN aoo_game_service_route r
  ON r.game_id=m.game_id AND r.play_version=m.old_version AND r.status='ACTIVE'
WHERE NOT EXISTS (
  SELECT 1 FROM aoo_game_service_route earlier
  WHERE earlier.game_id=r.game_id AND earlier.play_version=r.play_version
    AND earlier.status='ACTIVE'
    AND (earlier.priority<r.priority OR
      (earlier.priority=r.priority AND earlier.route_id<r.route_id))
)
ON DUPLICATE KEY UPDATE
  game_id=VALUES(game_id),play_version=VALUES(play_version),endpoint=VALUES(endpoint),
  priority=VALUES(priority),status='ACTIVE';
-- One immutable release is derived from the current canonical legacy release.
-- JSON snapshots are rewritten to the canonical identity without changing the
-- old release row.  The source hash is also carried into the UI snapshot so
-- Hall can form the rule-revision precondition used by room creation.
INSERT INTO aoo_game_release
  (release_id,game_id,play_version,release_version,release_scope,
   catalog_snapshot,rule_snapshot,ui_snapshot,component_snapshot,
   catalog_hash,rule_hash,ui_hash,component_hash,bundle_hash,
   status,rollout_percent,created_by,reason,validated_at,activated_at)
SELECT m.game_id*1000000000+2026100603,m.game_id,m.play_version,2026100603,r.release_scope,
       JSON_SET(CAST(REPLACE(REPLACE(CAST(r.catalog_snapshot AS CHAR),m.old_code,m.game_code),m.old_version,m.play_version) AS JSON),
         '$.gameId',m.game_id,'$.gameCode',m.game_code,
         '$.provider',CONCAT('com.aoo.bcg.poker.PdkGameProvider:',m.game_code),
         '$.playVersion',m.play_version,'$.regionCode',m.region_code),
       JSON_SET(CAST(REPLACE(REPLACE(CAST(r.rule_snapshot AS CHAR),m.old_code,m.game_code),m.old_version,m.play_version) AS JSON),
         '$.gameId',m.game_id,'$.gameCode',m.game_code,'$.playVersion',m.play_version,
         '$.sourceHash',m.source_hash,'$.fields',v.fields),
       JSON_SET(CAST(REPLACE(REPLACE(CAST(r.ui_snapshot AS CHAR),m.old_code,m.game_code),m.old_version,m.play_version) AS JSON),
         '$.gameId',m.game_id,'$.gameCode',m.game_code,'$.playVersion',m.play_version,
         '$.roomRuleSourceHash',m.source_hash,'$.roomRuleViewHash',m.source_hash,
         '$.fields',m.rule_fields),
       JSON_SET(CAST(REPLACE(REPLACE(CAST(r.component_snapshot AS CHAR),m.old_code,m.game_code),m.old_version,m.play_version) AS JSON),
         '$.gameId',m.game_id,'$.gameCode',m.game_code,'$.playVersion',m.play_version),
       SHA2(CONCAT(m.game_code,'|catalog|',m.play_version,'|',m.source_hash),256),
       SHA2(CONCAT(m.game_code,'|rules|',m.play_version,'|',m.source_hash),256),
       SHA2(CONCAT(m.game_code,'|ui|',m.play_version,'|',m.source_hash),256),
       SHA2(CONCAT(m.game_code,'|components|',m.play_version,'|',m.source_hash),256),
       SHA2(CONCAT(m.game_code,'|bundle|',m.play_version),256),
       'ACTIVE',100,r.created_by,
       CONCAT('Activate canonical PDK identity ',m.game_code,' at ',m.play_version),
       CURRENT_TIMESTAMP(3),CURRENT_TIMESTAMP(3)
FROM remaining_canonical_pdk m
JOIN aoo_game_release r
  ON r.game_id=m.game_id AND r.play_version=m.old_version AND r.status='ACTIVE'
JOIN remaining_canonical_pdk_validator v ON v.game_id=m.game_id
WHERE r.release_version=(SELECT MAX(oldr.release_version)
  FROM aoo_game_release oldr
  WHERE oldr.game_id=m.game_id AND oldr.play_version=m.old_version AND oldr.status='ACTIVE')
ON DUPLICATE KEY UPDATE
  game_id=VALUES(game_id),play_version=VALUES(play_version),release_version=VALUES(release_version),
  release_scope=VALUES(release_scope),catalog_snapshot=VALUES(catalog_snapshot),
  rule_snapshot=VALUES(rule_snapshot),ui_snapshot=VALUES(ui_snapshot),
  component_snapshot=VALUES(component_snapshot),catalog_hash=VALUES(catalog_hash),
  rule_hash=VALUES(rule_hash),ui_hash=VALUES(ui_hash),component_hash=VALUES(component_hash),
  bundle_hash=VALUES(bundle_hash),status='ACTIVE',rollout_percent=100,
  reason=VALUES(reason),validated_at=VALUES(validated_at),activated_at=VALUES(activated_at),
  retired_at=NULL;

INSERT INTO aoo_game_release_region
  (release_id,region_code,rollout_percent,status)
SELECT m.game_id*1000000000+2026100603,rr.region_code,rr.rollout_percent,'ACTIVE'
FROM remaining_canonical_pdk m
JOIN aoo_game_release r
  ON r.game_id=m.game_id AND r.play_version=m.old_version AND r.status='ACTIVE'
JOIN aoo_game_release_region rr ON rr.release_id=r.release_id AND rr.status='ACTIVE'
WHERE r.release_version=(SELECT MAX(oldr.release_version)
  FROM aoo_game_release oldr
  WHERE oldr.game_id=m.game_id AND oldr.play_version=m.old_version AND oldr.status='ACTIVE')
ON DUPLICATE KEY UPDATE rollout_percent=VALUES(rollout_percent),status='ACTIVE';
-- Compile and activate the room-create index.  The existing component chain
-- and resource UI are retained; only identity, rule fields and revision hashes
-- are changed.  This is the exact Hall configuration contract.
INSERT INTO aoo_compiled_room_create_index
  (game_id,region_code,play_version,index_generation,release_id,
   component_chain,rule_validator,ui_schema,lookup_hash,bundle_hash,
   lifecycle_state,compiled_at,validated_at,activated_at)
SELECT m.game_id,i.region_code,m.play_version,2026100603,
       m.game_id*1000000000+2026100603,
       CAST(REPLACE(REPLACE(CAST(i.component_chain AS CHAR),m.old_code,m.game_code),m.old_version,m.play_version) AS JSON),
       JSON_SET(CAST(REPLACE(REPLACE(CAST(i.rule_validator AS CHAR),m.old_code,m.game_code),m.old_version,m.play_version) AS JSON),
         '$.gameId',m.game_id,'$.gameCode',m.game_code,'$.playVersion',m.play_version,
         '$.source',CONCAT(m.game_code,'-room-rule-workbook'),
         '$.sourceHash',m.source_hash,'$.legacyFieldAliases',JSON_OBJECT(),
         '$.fields',v.fields),
       JSON_SET(CAST(REPLACE(REPLACE(CAST(i.ui_schema AS CHAR),m.old_code,m.game_code),m.old_version,m.play_version) AS JSON),
         '$.gameId',m.game_id,'$.gameCode',m.game_code,'$.playVersion',m.play_version,
         '$.roomRuleSourceHash',m.source_hash,'$.roomRuleViewHash',m.source_hash,
         '$.fields',m.rule_fields),
       SHA2(CONCAT(m.game_code,'|',i.region_code,'|',m.play_version,'|',m.source_hash),256),
       SHA2(CONCAT(m.game_code,'|bundle|',m.play_version),256),
       'ACTIVE',CURRENT_TIMESTAMP(3),CURRENT_TIMESTAMP(3),CURRENT_TIMESTAMP(3)
FROM remaining_canonical_pdk m
JOIN aoo_compiled_room_create_index i
  ON i.game_id=m.game_id AND i.play_version=m.old_version AND i.lifecycle_state='ACTIVE'
JOIN remaining_canonical_pdk_validator v ON v.game_id=m.game_id
ON DUPLICATE KEY UPDATE
  release_id=VALUES(release_id),component_chain=VALUES(component_chain),
  rule_validator=VALUES(rule_validator),ui_schema=VALUES(ui_schema),
  lookup_hash=VALUES(lookup_hash),bundle_hash=VALUES(bundle_hash),
  lifecycle_state='ACTIVE',validated_at=VALUES(validated_at),
  activated_at=VALUES(activated_at),retired_at=NULL;

INSERT INTO aoo_compiled_index_active
  (game_id,region_code,play_version,index_generation,release_id,cache_epoch,
   activated_by,activation_reason,activated_at)
SELECT m.game_id,i.region_code,m.play_version,2026100603,
       m.game_id*1000000000+2026100603,i.cache_epoch+1,i.activated_by,
       CONCAT('Activate canonical PDK identity ',m.game_code),CURRENT_TIMESTAMP(3)
FROM remaining_canonical_pdk m
JOIN aoo_compiled_index_active i
  ON i.game_id=m.game_id AND i.play_version=m.old_version
ON DUPLICATE KEY UPDATE
  play_version=VALUES(play_version),index_generation=VALUES(index_generation),
  release_id=VALUES(release_id),cache_epoch=GREATEST(aoo_compiled_index_active.cache_epoch,VALUES(cache_epoch)),
  activated_by=VALUES(activated_by),activation_reason=VALUES(activation_reason),
  activated_at=VALUES(activated_at);

INSERT INTO aoo_room_cost_policy
  (game_id,play_version,region_code,measure_kind,measure_value,round_count,
   player_count,payer_mode,currency_code,cost_minor,club_cost_minor,
   union_cost_minor,policy_version,content_hash,status)
SELECT m.game_id,m.play_version,p.region_code,p.measure_kind,p.measure_value,
       p.round_count,p.player_count,p.payer_mode,p.currency_code,p.cost_minor,
       p.club_cost_minor,p.union_cost_minor,p.policy_version+1,
       SHA2(CONCAT('canonical-pdk|',m.game_code,'|',m.play_version,'|',p.region_code,
         '|',p.measure_kind,'|',p.measure_value,'|',p.round_count,'|',p.player_count,
         '|',p.payer_mode,'|',p.currency_code,'|',p.cost_minor),256),'ACTIVE'
FROM remaining_canonical_pdk m
JOIN aoo_room_cost_policy p
  ON p.game_id=m.game_id AND p.play_version=m.old_version AND p.status='ACTIVE'
ON DUPLICATE KEY UPDATE
  measure_kind=VALUES(measure_kind),measure_value=VALUES(measure_value),
  cost_minor=VALUES(cost_minor),club_cost_minor=VALUES(club_cost_minor),
  union_cost_minor=VALUES(union_cost_minor),policy_version=VALUES(policy_version),
  content_hash=VALUES(content_hash),status='ACTIVE';
-- Retire only the canonical legacy operational pointers.  The rows remain in
-- place for historical room recovery and are never deleted or rewritten.
UPDATE aoo_game_service_route r
JOIN remaining_canonical_pdk m ON m.game_id=r.game_id AND r.play_version=m.old_version
SET r.status='OFFLINE'
WHERE r.status='ACTIVE';

UPDATE aoo_compiled_room_create_index i
JOIN remaining_canonical_pdk m ON m.game_id=i.game_id AND i.play_version=m.old_version
SET i.lifecycle_state='RETIRED',i.retired_at=COALESCE(i.retired_at,CURRENT_TIMESTAMP(3))
WHERE i.lifecycle_state='ACTIVE';

UPDATE aoo_game_release r
JOIN remaining_canonical_pdk m ON m.game_id=r.game_id AND r.play_version=m.old_version
SET r.status='RETIRED',r.retired_at=COALESCE(r.retired_at,CURRENT_TIMESTAMP(3))
WHERE r.status='ACTIVE';

UPDATE aoo_game_release_region rr
JOIN aoo_game_release r ON r.release_id=rr.release_id
JOIN remaining_canonical_pdk m ON m.game_id=r.game_id AND r.play_version=m.old_version
SET rr.status='RETIRED'
WHERE rr.status='ACTIVE';

UPDATE aoo_play_version p
JOIN remaining_canonical_pdk m ON m.game_id=p.game_id AND p.play_version=m.old_version
SET p.status='RETIRED',p.retired_at=COALESCE(p.retired_at,CURRENT_TIMESTAMP(3))
WHERE p.status IN ('ACTIVE','VALIDATED');

UPDATE aoo_room_cost_policy p
JOIN remaining_canonical_pdk m ON m.game_id=p.game_id AND p.play_version=m.old_version
SET p.status='RETIRED'
WHERE p.status='ACTIVE';

DROP TEMPORARY TABLE remaining_canonical_pdk_validator;
DROP TEMPORARY TABLE remaining_canonical_pdk;
COMMIT;
